# ======================================================================
@triton.jit
def add_kernel_0bf5b5d1(x_ptr, y_ptr, out_ptr, n_elements, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    x = tl.load(x_ptr + offsets, mask=mask)
    y = tl.load(y_ptr + offsets, mask=mask)
    tl.store(out_ptr + offsets, x + y, mask=mask)

def run_eqf_basic_add_kernel_0bf5b5d1(dev='cuda'):
    import torch
    x_ptr = torch.randn((4096,), device=dev, dtype=torch.float32)
    y_ptr = torch.randn((4096,), device=dev, dtype=torch.float32)
    out_ptr = torch.randn((4096,), device=dev, dtype=torch.float32)
    add_kernel_0bf5b5d1[(4, 1, 1)](x_ptr, y_ptr, out_ptr, 4096, BLOCK_SIZE=1024)
    return {'x_ptr': x_ptr, 'y_ptr': y_ptr, 'out_ptr': out_ptr}


# ======================================================================
# eqf_basic :: layernorm_kernel
# src: None
# validated: OK in={'X': [64, 320], 'Y': [64, 320], 'W': [320], 'B': [320]} 0.272ms
# ======================================================================
@triton.jit
def layernorm_kernel_85da57b8(X, Y, W, B, stride, N, eps, BLOCK_SIZE: tl.constexpr):
    row = tl.program_id(0)
    X += row * stride
    Y += row * stride
    cols = tl.arange(0, BLOCK_SIZE)
    mask = cols < N
    x = tl.load(X + cols, mask=mask, other=0.0)
    mean = tl.sum(x, axis=0) / N
    xc = tl.where(mask, x - mean, 0.0)
    var = tl.sum(xc * xc, axis=0) / N
    rstd = 1.0 / tl.sqrt(var + eps)
    w = tl.load(W + cols, mask=mask)
    b = tl.load(B + cols, mask=mask)
    tl.store(Y + cols, xc * rstd * w + b, mask=mask)

def run_eqf_basic_layernorm_kernel_85da57b8(dev='cuda'):
    import torch
    X = torch.randn((64, 320), device=dev, dtype=torch.float32)
    Y = torch.randn((64, 320), device=dev, dtype=torch.float32)
    W = torch.randn((320,), device=dev, dtype=torch.float32)
    B = torch.randn((320,), device=dev, dtype=torch.float32)
    layernorm_kernel_85da57b8[(64, 1, 1)](X, Y, W, B, 320, 320, 1e-05, BLOCK_SIZE=512)
    return {'X': X, 'Y': Y, 'W': W, 'B': B}


