# eqf_basic :: softmax_kernel
# src: None
# validated: OK in={'out_ptr': [128, 500], 'in_ptr': [128, 500]} 0.233ms
# ======================================================================
@triton.jit
def softmax_kernel_f21c78fe(out_ptr, in_ptr, in_stride, out_stride, n_cols, BLOCK_SIZE: tl.constexpr):
    row = tl.program_id(0)
    cols = tl.arange(0, BLOCK_SIZE)
    mask = cols < n_cols
    x = tl.load(in_ptr + row * in_stride + cols, mask=mask, other=-float('inf'))
    x = x - tl.max(x, axis=0)
    num = tl.exp(x)
    den = tl.sum(num, axis=0)
    tl.store(out_ptr + row * out_stride + cols, num / den, mask=mask)

def run_eqf_basic_softmax_kernel_f21c78fe(dev='cuda'):
    import torch
    out_ptr = torch.randn((128, 500), device=dev, dtype=torch.float32)
    in_ptr = torch.randn((128, 500), device=dev, dtype=torch.float32)
    softmax_kernel_f21c78fe[(128, 1, 1)](out_ptr, in_ptr, 500, 500, 500, BLOCK_SIZE=512)
    return {'out_ptr': out_ptr, 'in_ptr': in_ptr}


