@triton.jit
def softmax_bwd_kernel_04ce474d(p, dp, ds, D: tl.constexpr, B: tl.constexpr):
    i_n = tl.program_id(0)
    o_d = tl.arange(0, B)
    m_d = o_d < D
    b_p = tl.load(p + i_n * D + o_d, mask=m_d, other=0.0)
    b_dp = tl.load(dp + i_n * D + o_d, mask=m_d, other=0.0)
