def _any_dims_kernel_o1_r1_d1d1fbdc(inp, out, output_shape0, input_output_stride0, output_stride0, reduce_shape0, input_reduce_stride0, BLOCK_M: tl.constexpr, BLOCK_N: tl.constexpr):
    output = output_shape0
    input_per_output = reduce_shape0
    output_tiles = tl.cdiv(output, BLOCK_M)
    pid = tl.program_id(0)
    pid_y = pid % output_tiles
    pid_x = pid // output_tiles
    output_offsets_linear = (pid_y * BLOCK_M + tl.arange(0, BLOCK_M)).to(tl.int64)
    reduce_offsets_linear = (pid_x * BLOCK_N + tl.arange(0, BLOCK_N)).to(tl.int64)
    output_mask = output_offsets_linear < output
    reduce_mask = reduce_offsets_linear < input_per_output
    input_output_offsets = tl.zeros((BLOCK_M,), dtype=tl.int64)
    output_offsets = tl.zeros((BLOCK_M,), dtype=tl.int64)
    output_linear = output_offsets_linear
    out_idx0 = output_linear % output_shape0
    input_output_offsets += out_idx0 * input_output_stride0
    output_offsets += out_idx0 * output_stride0
    input_reduce_offsets = tl.zeros((BLOCK_N,), dtype=tl.int64)
    reduce_linear = reduce_offsets_linear
    red_idx0 = reduce_linear % reduce_shape0
    input_reduce_offsets += red_idx0 * input_reduce_stride0
    input_offsets = input_output_offsets[:, None] + input_reduce_offsets[None, :]
    active = tl.load(out + output_offsets, mask=output_mask, other=1) == 0
    mask = output_mask[:, None] & reduce_mask[None, :] & active[:, None]
    vals = tl.load(inp + input_offsets, mask=mask, other=0.0)
    local_any = tl.max(vals != 0, axis=1).to(tl.int32)
    tl.atomic_max(out + output_offsets, local_any, mask=output_mask & active & (local_any != 0))

