# flaggems :: _complete_svd_factor_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/svd.py#L3327
# validated: OK in={'THIN': [3, 3], 'FULL': [3, 3]} 0.293ms
# ======================================================================
@triton.jit
def _complete_svd_factor_kernel_e266834b(THIN, FULL, ROWS: tl.constexpr, THIN_COLS: tl.constexpr, FULL_COLS: tl.constexpr, BLOCK_ROWS: tl.constexpr, BLOCK_COLS: tl.constexpr):
    batch = tl.program_id(0)
    rows = tl.arange(0, BLOCK_ROWS)
    cols = tl.arange(0, BLOCK_COLS)
    row_mask = rows < ROWS
    col_mask = cols < FULL_COLS
    vals = tl.load(THIN + batch * ROWS * THIN_COLS + rows[:, None] * THIN_COLS + cols[None, :], mask=row_mask[:, None] & (cols[None, :] < THIN_COLS), other=0.0)
    identity = tl.where(rows[:, None] == cols[None, :], 1.0, 0.0)
    vals = tl.where(cols[None, :] < THIN_COLS, vals, identity)
    for c in tl.static_range(0, 64):
        cur_mask = c < FULL_COLS
        cur = tl.sum(tl.where(cols[None, :] == c, vals, 0.0), axis=1)
        for p in tl.static_range(0, c):
            prev = tl.sum(tl.where(cols[None, :] == p, vals, 0.0), axis=1)
            coeff = tl.sum(tl.where(row_mask, prev * cur, 0.0), axis=0)
            cur -= prev * coeff
        norm_sq = tl.sum(tl.where(row_mask, cur * cur, 0.0), axis=0)
        inv_norm = tl.rsqrt(tl.maximum(norm_sq, 1e-20))
        cur *= inv_norm
        vals = tl.where((cols[None, :] == c) & cur_mask, cur[:, None], vals)
    out_base = FULL + batch * ROWS * FULL_COLS
    offsets = rows[:, None] * FULL_COLS + cols[None, :]
    mask = row_mask[:, None] & col_mask[None, :]
    tl.store(out_base + offsets, vals, mask=mask)

