# flaggems :: _complex_svd_pick_orthonormal_v_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/svd.py#L3041
# validated: OK in={'V_REAL': [1, 6, 6], 'V_RI': [1, 3, 3, 2]} 0.247ms
# ======================================================================
@triton.jit
def _complex_svd_pick_orthonormal_v_kernel_e65b022b(V_REAL, V_RI, ROWS: tl.constexpr, K: tl.constexpr, REAL_K: tl.constexpr, BLOCK_ROWS: tl.constexpr, BLOCK_K: tl.constexpr):
    batch = tl.program_id(0)
    rows = tl.arange(0, BLOCK_ROWS)
    cols = tl.arange(0, BLOCK_K)
    row_mask = rows < ROWS
    col_mask = cols < K
    src_cols = cols * 2
    base = V_REAL + batch * (2 * ROWS) * REAL_K
    vr = tl.load(base + rows[:, None] * REAL_K + src_cols[None, :], mask=row_mask[:, None] & col_mask[None, :], other=0.0)
    vi = tl.load(base + (ROWS + rows[:, None]) * REAL_K + src_cols[None, :], mask=row_mask[:, None] & col_mask[None, :], other=0.0)
    for c in tl.static_range(0, 16):
        cur_mask = c < K
        cur_r = tl.sum(tl.where(cols[None, :] == c, vr, 0.0), axis=1)
        cur_i = tl.sum(tl.where(cols[None, :] == c, vi, 0.0), axis=1)
        for p in tl.static_range(0, c):
            prev_r = tl.sum(tl.where(cols[None, :] == p, vr, 0.0), axis=1)
            prev_i = tl.sum(tl.where(cols[None, :] == p, vi, 0.0), axis=1)
            coeff_r = tl.sum(tl.where(row_mask, prev_r * cur_r + prev_i * cur_i, 0.0), axis=0)
            coeff_i = tl.sum(tl.where(row_mask, prev_r * cur_i - prev_i * cur_r, 0.0), axis=0)
            cur_r -= prev_r * coeff_r - prev_i * coeff_i
            cur_i -= prev_r * coeff_i + prev_i * coeff_r
        norm_sq = tl.sum(tl.where(row_mask, cur_r * cur_r + cur_i * cur_i, 0.0), axis=0)
        inv_norm = tl.rsqrt(tl.maximum(norm_sq, 1e-20))
        cur_r *= inv_norm
        cur_i *= inv_norm
        vr = tl.where((cols[None, :] == c) & cur_mask, cur_r[:, None], vr)
        vi = tl.where((cols[None, :] == c) & cur_mask, cur_i[:, None], vi)
    out_base = V_RI + batch * ROWS * K * 2
    offsets = rows[:, None] * K + cols[None, :]
    mask = row_mask[:, None] & col_mask[None, :]
    tl.store(out_base + offsets * 2, vr, mask=mask)
    tl.store(out_base + offsets * 2 + 1, vi, mask=mask)

