# flaggems :: _ctc_loss_init_grad_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/ctc_loss.py#L395
# validated: OK in={'log_probs': [12, 3, 7], 'input_lengths': [3], 'target_lengths': [3], 'neg_log_likelihood': [3], 'grad_output': [3], 'grad_input': [12, 3, 7]} 0.273ms
# ======================================================================
@triton.jit
def _ctc_loss_init_grad_kernel_62cfba36(log_probs, input_lengths, target_lengths, neg_log_likelihood, grad_output, grad_input, total: tl.constexpr, T: tl.constexpr, N: tl.constexpr, C: tl.constexpr, REDUCTION: tl.constexpr, ZERO_INFINITY: tl.constexpr, BLOCK: tl.constexpr):
    offsets = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offsets < total
    batch = offsets // C % N
    t = offsets // (N * C)
    input_len = tl.load(input_lengths + batch, mask=mask, other=0)
    target_len = tl.load(target_lengths + batch, mask=mask, other=1)
    nll = tl.load(neg_log_likelihood + batch, mask=mask, other=0.0).to(tl.float32)
    if REDUCTION == 0:
        scale = tl.load(grad_output + batch, mask=mask, other=0.0).to(tl.float32)
    else:
        scale = tl.load(grad_output).to(tl.float32)
        if REDUCTION == 1:
            denom = tl.maximum(target_len, 1).to(tl.float32) * N
            scale = scale / denom
    if ZERO_INFINITY:
        scale = tl.where(nll == float('inf'), 0.0, scale)
    logp = tl.load(log_probs + offsets, mask=mask, other=-float('inf')).to(tl.float32)
    grad = tl.where((t < input_len) & mask, tl.exp(logp) * scale, 0.0)
    nan_grad = float('nan')
    grad = tl.where((t < input_len) & mask & (scale != 0.0) & (logp == -float('inf')), nan_grad, grad)
    if not ZERO_INFINITY:
        grad = tl.where((t < input_len) & mask & (nll == float('inf')), nan_grad, grad)
    tl.store(grad_input + offsets, grad, mask=mask)

def run_flaggems__ctc_loss_init_grad_kernel_62cfba36(dev='cuda'):
    import torch
    log_probs = torch.randn((12, 3, 7), device=dev, dtype=torch.float32)
    input_lengths = torch.zeros((3,), device=dev, dtype=torch.int64)
    target_lengths = torch.zeros((3,), device=dev, dtype=torch.int64)
    neg_log_likelihood = torch.randn((3,), device=dev, dtype=torch.float32)
    grad_output = torch.randn((3,), device=dev, dtype=torch.float32)
    grad_input = torch.randn((12, 3, 7), device=dev, dtype=torch.float32)
    _ctc_loss_init_grad_kernel_62cfba36[(1, 1, 1)](log_probs, input_lengths, target_lengths, neg_log_likelihood, grad_output, grad_input, total=252, T=12, N=3, C=7, REDUCTION=0, ZERO_INFINITY=False, BLOCK=256)
    return {'log_probs': log_probs, 'input_lengths': input_lengths, 'target_lengths': target_lengths, 'neg_log_likelihood': neg_log_likelihood, 'grad_output': grad_output, 'grad_input': grad_input}


