# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/svd.py#L1831
# validated: OK in={'A_WORK': [1, 32, 64], 'V_WORK': [1, 32, 32], 'S_WORK': [1, 32], 'U': [1, 64, 32], 'S': [1, 32], 'V': [1, 32, 32]} 0.276ms
# ======================================================================
@triton.jit
def _cyclic_jacobi_finalize_kernel_4665c432(A_WORK, V_WORK, S_WORK, U, S, V, M: tl.constexpr, N: tl.constexpr, K: tl.constexpr, ROWS: tl.constexpr, TALL: tl.constexpr, BLOCK_R: tl.constexpr, BLOCK_K: tl.constexpr):
    batch = tl.program_id(0)
    col = tl.program_id(1)
    rows = tl.arange(0, BLOCK_R)
    basis_cols = tl.arange(0, BLOCK_K)
    row_mask = rows < ROWS
    basis_mask = basis_cols < K
    eps = 1e-20
    s_col = tl.load(S_WORK + batch * K + col)
    rank = tl.full((), 0, dtype=tl.int32)
    for other in tl.static_range(0, K):
        s_other = tl.load(S_WORK + batch * K + other)
        rank += ((s_other > s_col) | (s_other == s_col) & (other < col)).to(tl.int32)
    aw_base = A_WORK + batch * K * ROWS
    vw_base = V_WORK + batch * K * K
    col_vals = tl.load(aw_base + col * ROWS + rows, mask=row_mask, other=0.0)
    inv_norm = tl.where(s_col > eps, 1.0 / s_col, 0.0)
    basis = tl.load(vw_base + col * K + basis_cols, mask=basis_mask, other=0.0)
    tl.store(S + batch * K + rank, s_col)
    if TALL:
        tl.store(U + batch * M * K + rows * K + rank, col_vals * inv_norm, mask=row_mask)
        tl.store(V + batch * N * K + basis_cols * K + rank, basis, mask=basis_mask)
    else:
        tl.store(U + batch * M * K + basis_cols * K + rank, basis, mask=basis_mask)
        tl.store(V + batch * N * K + rows * K + rank, col_vals * inv_norm, mask=row_mask)

