# flaggems :: _cyclic_jacobi_init_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/svd.py#L1596
# validated: OK in={'A': [1, 64, 32], 'A_WORK': [1, 32, 64], 'V_WORK': [1, 32, 32]} 0.264ms
# ======================================================================
@triton.jit
def _cyclic_jacobi_init_kernel_cb1f2577(A, A_WORK, V_WORK, M: tl.constexpr, N: tl.constexpr, K: tl.constexpr, ROWS: tl.constexpr, TALL: tl.constexpr, BLOCK_R: tl.constexpr, BLOCK_K: tl.constexpr):
    batch = tl.program_id(0)
    col = tl.program_id(1)
    rows = tl.arange(0, BLOCK_R)
    basis_cols = tl.arange(0, BLOCK_K)
    row_mask = rows < ROWS
    basis_mask = basis_cols < K
    a_base = A + batch * M * N
    aw_base = A_WORK + batch * K * ROWS
    vw_base = V_WORK + batch * K * K
    if TALL:
        vals = tl.load(a_base + rows * N + col, mask=row_mask, other=0.0).to(tl.float32)
    else:
        vals = tl.load(a_base + col * N + rows, mask=row_mask, other=0.0).to(tl.float32)
    tl.store(aw_base + col * ROWS + rows, vals, mask=row_mask)
    ident = tl.where(basis_cols == col, 1.0, 0.0)
    tl.store(vw_base + col * K + basis_cols, ident, mask=basis_mask)

