# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/svd.py#L1812
# validated: OK in={'A_WORK': [1, 32, 64], 'S_WORK': [1, 32]} 0.259ms
# ======================================================================
@triton.jit
def _cyclic_jacobi_norm_kernel_5c4cf2cf(A_WORK, S_WORK, K: tl.constexpr, ROWS: tl.constexpr, BLOCK_R: tl.constexpr):
    batch = tl.program_id(0)
    col = tl.program_id(1)
    rows = tl.arange(0, BLOCK_R)
    mask = rows < ROWS
    aw_base = A_WORK + batch * K * ROWS
    vals = tl.load(aw_base + col * ROWS + rows, mask=mask, other=0.0)
    norm = tl.sqrt(tl.sum(vals * vals))
    tl.store(S_WORK + batch * K + col, norm)

