# flaggems :: _embedding_dense_backward_kernel_scale_by_freq
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/embedding_dense_backward.py#L56
# validated: OK in={'grad_output_ptr': [8, 8], 'indices_ptr': [8], 'counts_ptr': [16], 'grad_weight_ptr': [16, 8]} 0.279ms
# ======================================================================
@triton.jit
def _embedding_dense_backward_kernel_scale_by_freq_4eb326c5(grad_output_ptr, indices_ptr, counts_ptr, grad_weight_ptr, num_weights, padding_idx, BLOCK_D: tl.constexpr, EMBED_DIM: tl.constexpr):
    pid_n = tl.program_id(0)
    pid_d = tl.program_id(1)
    offs_d = pid_d * BLOCK_D + tl.arange(0, BLOCK_D)
    mask_d = offs_d < EMBED_DIM
    idx = tl.load(indices_ptr + pid_n).to(tl.int32)
    valid = (idx != padding_idx) & (idx >= 0) & (idx < num_weights)
    go_ptrs = grad_output_ptr + pid_n * EMBED_DIM + offs_d
    go = tl.load(go_ptrs, mask=mask_d, other=0.0)
    cnt = tl.load(counts_ptr + idx, mask=valid, other=1)
    go = go / cnt
    gw_ptrs = grad_weight_ptr + idx * EMBED_DIM + offs_d
    mask = mask_d & valid
    tl.atomic_add(gw_ptrs, go, mask=mask)

