    import torch
    x1_ptr = torch.randn((4, 8), device=dev, dtype=torch.float32)
    x2_ptr = torch.randn((5, 8), device=dev, dtype=torch.float32)
    output_ptr = torch.randn((4, 5), device=dev, dtype=torch.float32)
