# flaggems :: _fht_kernel_1d
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/hadamard_transform.py#L325
# validated: OK in={'X_ptr': [3, 512], 'OUT_ptr': [3, 512]} 0.229ms
# ======================================================================
@triton.jit
def _butterfly_stage_1d_f0e56ad2(x, BLOCK_SIZE: tl.constexpr, STRIDE: tl.constexpr):
    """One butterfly stage on a 1D vector."""
    GRP: tl.constexpr = BLOCK_SIZE // (2 * STRIDE)
    if STRIDE == 1:
        x2 = tl.reshape(x, (GRP, 2))
        a, b = tl.split(x2)
        return tl.reshape(tl.join(a + b, a - b), (BLOCK_SIZE,))
    else:
        x3 = tl.reshape(x, (GRP, 2, STRIDE))
        x3 = tl.permute(x3, (0, 2, 1))
        a, b = tl.split(x3)
        x3 = tl.join(a + b, a - b)
        x3 = tl.permute(x3, (0, 2, 1))
        return tl.reshape(x3, (BLOCK_SIZE,))

@triton.jit
def _fht_kernel_1d_f0e56ad2(X_ptr, OUT_ptr, scale, stride_x_row, stride_out_row, DIM: tl.constexpr, LOG_N: tl.constexpr, BLOCK_SIZE: tl.constexpr, INPUT_IS_FP16: tl.constexpr, INPUT_IS_BF16: tl.constexpr):
    """FHT butterfly — 1D single-row kernel, reversed stage order."""
    pid = tl.program_id(0)
    col_offs = tl.arange(0, BLOCK_SIZE)
    in_ptr = X_ptr + pid * stride_x_row + col_offs
    out_ptr = OUT_ptr + pid * stride_out_row + col_offs
    x = tl.load(in_ptr).to(tl.float32)
    for s_rev in tl.static_range(LOG_N):
        x = _butterfly_stage_1d_f0e56ad2(x, BLOCK_SIZE, 1 << LOG_N - 1 - s_rev)
    x = x * scale
    if INPUT_IS_FP16:
        tl.store(out_ptr, x.to(tl.float16), eviction_policy='evict_first')
    elif INPUT_IS_BF16:
        tl.store(out_ptr, x.to(tl.bfloat16), eviction_policy='evict_first')
    else:
        tl.store(out_ptr, x, eviction_policy='evict_first')

