@triton.jit
def _hypot_kernel_a76fb6a4(x_ptr, y_ptr, out_ptr, n_elements, BLOCK_SIZE: tl.constexpr, OUT_DTYPE: tl.constexpr, COMPUTE_DTYPE: tl.constexpr):
    pid = tl.program_id(axis=0)
    block_start = pid * BLOCK_SIZE
    offsets = block_start + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    x = tl.load(x_ptr + offsets, mask=mask, other=0)
    y = tl.load(y_ptr + offsets, mask=mask, other=0)
    xf = x.to(COMPUTE_DTYPE)
    yf = y.to(COMPUTE_DTYPE)
    ax = tl.abs(xf)
    ay = tl.abs(yf)
    t = tl.maximum(ax, ay)
    m = tl.minimum(ax, ay)
    t_nz = tl.where(t > 0, t, 1).to(COMPUTE_DTYPE)
    r = m / t_nz
    res = tl.where(t > 0, t * tl.sqrt(1 + r * r), m)
    out_val = res.to(OUT_DTYPE)
    tl.store(out_ptr + offsets, out_val, mask=mask)

