    grad_output_ptr = torch.randn((6,), device=dev, dtype=torch.float16)
    x1_ptr = torch.randn((6,), device=dev, dtype=torch.float16)
    x2_ptr = torch.randn((6,), device=dev, dtype=torch.float16)
