    import torch
    x1_ptr = torch.randn((6,), device=dev, dtype=torch.float16)
    x2_ptr = torch.randn((6,), device=dev, dtype=torch.float16)
    target_ptr = torch.randn((6,), device=dev, dtype=torch.float16)
    out_ptr = torch.randn((6,), device=dev, dtype=torch.float16)
