def _axis_for_pair_01bc27e8(pair, axis_map, st: tl.constexpr, sh: tl.constexpr, sw: tl.constexpr, interleaved: tl.constexpr, glm: tl.constexpr, BLOCK: tl.constexpr):
    if glm:
        axis = tl.load(axis_map + pair, mask=True, other=0).to(tl.int32)
    elif interleaved:
        mod3 = pair % 3
        is_h = (mod3 == 1) & (pair < sh * 3)
        is_w = (mod3 == 2) & (pair < sw * 3)
        axis = tl.where(is_h, 1, tl.where(is_w, 2, 0)).to(tl.int32)
    else:
        axis = tl.where(pair < st, 0, tl.where(pair < st + sh, 1, 2)).to(tl.int32)
    return axis

@triton.jit
def _mrope_pair_kernel_01bc27e8(q, k, cache, pos, axis_map, n_tokens: tl.constexpr, q_heads: tl.constexpr, k_heads: tl.constexpr, head_size: tl.constexpr, rotary_dim: tl.constexpr, st: tl.constexpr, sh: tl.constexpr, sw: tl.constexpr, interleaved: tl.constexpr, glm: tl.constexpr, neox: tl.constexpr, GROUP: tl.constexpr, BLOCK: tl.constexpr):
    row = tl.program_id(0)
    head_group = tl.program_id(1) * GROUP
    heads = head_group + tl.arange(0, GROUP)
    pair = tl.arange(0, BLOCK)
