            new_ap = c * ap - s_rot * aq
            new_aq = s_rot * ap + c * aq
            tl.store(aw_base + p2 * ROWS + rows, new_ap, mask=row_mask)
            tl.store(aw_base + q2 * ROWS + rows, new_aq, mask=row_mask)
