    import torch
    flat_ptr = torch.zeros((8, 1), device=dev, dtype=torch.int16)
    indices_ptr = torch.zeros((8, 1), device=dev, dtype=torch.int16)
    group_id_ptr = torch.zeros((8, 1), device=dev, dtype=torch.int16)
    out_ptr = torch.zeros((8,), device=dev, dtype=torch.int64)
    _unique_dim_build_key_kernel_3ca9514c[(1, 1, 1)](flat_ptr, indices_ptr, group_id_ptr, out_ptr, 8, 1, 0, KEY_OFFSET=32768, KEY_SCALE=65536, REMAP_KIND=0, FIRST=True, BLOCK_SIZE=1024)
