# flaggems :: _upsample_bicubic2d_row_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/upsample_bicubic2d.py#L22
# validated: OK in={'in_ptr': [1, 1, 8, 8], 'out_ptr': [1, 1, 16, 16]} 0.215ms
# ======================================================================
@triton.jit
def cubic_weight_efdf594c(d, a: tl.constexpr):
    ad = tl.abs(d)
    ad2 = ad * ad
    ad3 = ad2 * ad
    w1 = (a + 2.0) * ad3 - (a + 3.0) * ad2 + 1.0
    w2 = a * ad3 - 5.0 * a * ad2 + 8.0 * a * ad - 4.0 * a
    return tl.where(ad <= 1.0, w1, tl.where(ad < 2.0, w2, 0.0))

@triton.jit
def _upsample_bicubic2d_row_kernel_efdf594c(in_ptr, out_ptr, N, C, H_in, W_in, H_out, W_out, strideN, strideC, strideH, strideW, out_strideN, out_strideC, out_strideH, out_strideW, scale_h, scale_w, align_corners: tl.constexpr, BLOCK_W: tl.constexpr):
    pid = tl.program_id(0)
    num_w_blocks = tl.cdiv(W_out, BLOCK_W)
    pid_w = pid % num_w_blocks
    row_id = pid // num_w_blocks
    y_out = row_id % H_out
    nc = row_id // H_out
    c = nc % C
    n = nc // C
    fy = y_out * 1.0
    if align_corners:
        in_y = fy * scale_h
    else:
        in_y = (fy + 0.5) * scale_h - 0.5
    y0f = tl.floor(in_y)
    y0 = y0f.to(tl.int32)
    ty = in_y - y0f
    y_m1 = tl.maximum(0, tl.minimum(H_in - 1, y0 - 1))
    y_0 = tl.maximum(0, tl.minimum(H_in - 1, y0 + 0))
    y_p1 = tl.maximum(0, tl.minimum(H_in - 1, y0 + 1))
    y_p2 = tl.maximum(0, tl.minimum(H_in - 1, y0 + 2))
    a = -0.75
    wy0 = cubic_weight_efdf594c(1.0 + ty, a)
    wy1 = cubic_weight_efdf594c(ty, a)
    wy2 = cubic_weight_efdf594c(1.0 - ty, a)
    wy3 = cubic_weight_efdf594c(2.0 - ty, a)
    n_64 = n.to(tl.int64)
    c_64 = c.to(tl.int64)
    base_ptr = in_ptr + n_64 * strideN + c_64 * strideC
    row_m1_ptr = base_ptr + y_m1.to(tl.int64) * strideH
    row_0_ptr = base_ptr + y_0.to(tl.int64) * strideH
    row_p1_ptr = base_ptr + y_p1.to(tl.int64) * strideH
