# flaggems :: bernoulli_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/bernoulli.py#L18
# NOT runnable (not-runnable): TypeError: 'function' object is not subscriptable
# ======================================================================
def bernoulli_kernel_d7933020(out_ptr, X_ptr, N, philox_seed, philox_offset, BLOCK: tl.constexpr):
    UNROLL: tl.constexpr = 4
    philox_seed = philox_seed.to(tl.int64)
    philox_offset = philox_offset.to(tl.int64)
    c0 = (philox_offset & 4294967295).to(tl.uint32)
    c1 = (philox_offset >> 32 & 4294967295).to(tl.uint32)
    i4 = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    c0 += i4
    _O = c0 * 0
    r0, r1, r2, r3 = tl.philox(philox_seed, c0, c1, _O, _O)
    r0 = uint_to_uniform_float(r0)
    r1 = uint_to_uniform_float(r1)
    r2 = uint_to_uniform_float(r2)
    r3 = uint_to_uniform_float(r3)
    off_0 = tl.program_id(0) * BLOCK * UNROLL + tl.arange(0, BLOCK)
    off_1 = off_0 + BLOCK
    off_2 = off_1 + BLOCK
    off_3 = off_2 + BLOCK
    x0 = tl.load(X_ptr + off_0, mask=off_0 < N, other=0.0)
    x1 = tl.load(X_ptr + off_1, mask=off_1 < N, other=0.0)
    x2 = tl.load(X_ptr + off_2, mask=off_2 < N, other=0.0)
    x3 = tl.load(X_ptr + off_3, mask=off_3 < N, other=0.0)
    y0 = tl.where(r0 < x0, 1.0, 0.0)
    y1 = tl.where(r1 < x1, 1.0, 0.0)
    y2 = tl.where(r2 < x2, 1.0, 0.0)
    y3 = tl.where(r3 < x3, 1.0, 0.0)
    tl.store(out_ptr + off_0, y0, mask=off_0 < N)
    tl.store(out_ptr + off_1, y1, mask=off_1 < N)
    tl.store(out_ptr + off_2, y2, mask=off_2 < N)
    tl.store(out_ptr + off_3, y3, mask=off_3 < N)

def run_flaggems_bernoulli_kernel_d7933020(dev='cuda'):
    import torch
    out_ptr = torch.randn((20, 320, 15), device=dev, dtype=torch.float16)
    X_ptr = torch.randn((20, 320, 15), device=dev, dtype=torch.float16)
    bernoulli_kernel_d7933020[(375, 1, 1)](out_ptr, X_ptr, 96000, 3272458114397763, 360196, BLOCK=64)
