# flaggems :: bernoulli_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/bernoulli_.py#L18
# NOT runnable (not-runnable): TypeError: 'function' object is not subscriptable
# ======================================================================
def bernoulli_kernel_fa939965(out_ptr, N, p, philox_seed, philox_offset, BLOCK: tl.constexpr):
    philox_seed = philox_seed.to(tl.int64)
    philox_offset = philox_offset.to(tl.int64)
    c0 = (philox_offset & 4294967295).to(tl.uint32)
    c1 = (philox_offset >> 32 & 4294967295).to(tl.uint32)
    i4 = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    c0 += i4
    _O = c0 * 0
    r0, r1, r2, r3 = tl.philox(philox_seed, c0, c1, _O, _O)
    u0 = uint_to_uniform_float(r0)
    u1 = uint_to_uniform_float(r1)
    u2 = uint_to_uniform_float(r2)
    u3 = uint_to_uniform_float(r3)
    y0 = tl.where(u0 < p, 1.0, 0.0)
    y1 = tl.where(u1 < p, 1.0, 0.0)
    y2 = tl.where(u2 < p, 1.0, 0.0)
    y3 = tl.where(u3 < p, 1.0, 0.0)
    off_0 = tl.program_id(0) * BLOCK * 4 + tl.arange(0, BLOCK)
    off_1 = off_0 + BLOCK
    off_2 = off_1 + BLOCK
    off_3 = off_2 + BLOCK
    tl.store(out_ptr + off_0, y0, mask=off_0 < N, eviction_policy='evict_first')
    tl.store(out_ptr + off_1, y1, mask=off_1 < N, eviction_policy='evict_first')
    tl.store(out_ptr + off_2, y2, mask=off_2 < N, eviction_policy='evict_first')
    tl.store(out_ptr + off_3, y3, mask=off_3 < N, eviction_policy='evict_first')

def run_flaggems_bernoulli_kernel_fa939965(dev='cuda'):
    import torch
    out_ptr = torch.randn((20, 320, 15), device=dev, dtype=torch.float16)
    bernoulli_kernel_fa939965[(24, 1, 1)](out_ptr, 96000, 0.5, 3272458114397763, 192, BLOCK=1024)
    return {'out_ptr': out_ptr}


