# flaggems :: bincount_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/bincount.py#L12
# validated: OK in={'inp_ptr': [16], 'out_ptr': [10]} 0.206ms
# ======================================================================
@triton.jit
def bincount_kernel_ac709e0d(inp_ptr, out_ptr, N, BLOCK_SIZE: tl.constexpr):
    """Kernel for bincount without weights."""
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < N
    indices = tl.load(inp_ptr + offsets, mask=mask, other=0)
    ones = tl.full((BLOCK_SIZE,), 1, dtype=tl.int64)
    tl.atomic_add(out_ptr + indices, ones, mask=mask, sem='relaxed')

def run_flaggems_bincount_kernel_ac709e0d(dev='cuda'):
    import torch
    inp_ptr = torch.zeros((16,), device=dev, dtype=torch.int64)
    out_ptr = torch.zeros((10,), device=dev, dtype=torch.int64)
    bincount_kernel_ac709e0d[(1, 1, 1)](inp_ptr, out_ptr, 16, BLOCK_SIZE=1024)
    return {'inp_ptr': inp_ptr, 'out_ptr': out_ptr}


