# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/bincount.py#L34
# validated: OK in={'inp_ptr': [16], 'weights_ptr': [16], 'out_ptr': [10]} 0.284ms
# ======================================================================
@triton.jit
def bincount_weights_kernel_ccff779c(inp_ptr, weights_ptr, out_ptr, N, BLOCK_SIZE: tl.constexpr):
    """Kernel for bincount with weights."""
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < N
    indices = tl.load(inp_ptr + offsets, mask=mask, other=0)
    weights = tl.load(weights_ptr + offsets, mask=mask, other=0.0)
    tl.atomic_add(out_ptr + indices, weights, mask=mask, sem='relaxed')

def run_flaggems_bincount_weights_kernel_ccff779c(dev='cuda'):
    import torch
    inp_ptr = torch.zeros((16,), device=dev, dtype=torch.int64)
    weights_ptr = torch.randn((16,), device=dev, dtype=torch.float32)
    out_ptr = torch.randn((10,), device=dev, dtype=torch.float32)
    bincount_weights_kernel_ccff779c[(1, 1, 1)](inp_ptr, weights_ptr, out_ptr, 16, BLOCK_SIZE=1024)
    return {'inp_ptr': inp_ptr, 'weights_ptr': weights_ptr, 'out_ptr': out_ptr}


