# flaggems :: block_cumsum_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/cumsum.py#L392
# NOT runnable (not-runnable): TypeError: 'function' object is not subscriptable
# ======================================================================
import flag_gems.utils.triton_lang_extension as ext_babcf48e

def block_cumsum_kernel_babcf48e(inp, out, sums, r, t, R, K, r_stride, k_stride, out_r_stride, out_k_stride, OUTPUT_SUMS: tl.constexpr, NORMALIZE: tl.constexpr, HAS_OUT_LAYOUT: tl.constexpr, TILE: tl.constexpr):
    gridx = ext_babcf48e.program_id(0).to(tl.int64)
    gridy = ext_babcf48e.program_id(1).to(tl.int64)
    n_chunks = ext_babcf48e.num_programs(0)
    for row in range(gridy * r, min((gridy + 1) * r, R)):
        curr_cumsum = tl.zeros((1,), tl.float32)
        row_offset = row * r_stride
        cols = gridx * t * TILE + tl.arange(0, TILE)
        for ti in range(0, t):
            cols_offset = cols * k_stride
            x = tl.load(inp + row_offset + cols_offset, mask=cols < K, other=0)
            if x.dtype.is_fp16() | x.dtype.is_bf16():
                x = x.to(tl.float32)
            tile_sum = tl.sum(x, 0)[None]
            tile_cumsum = tl.cumsum(x, 0) + curr_cumsum
            curr_cumsum += tile_sum
            if HAS_OUT_LAYOUT:
                cols_offset = cols * out_k_stride
                row_offset = row * out_r_stride
            tl.store(out + row_offset + cols_offset, tile_cumsum, mask=cols < K)
            if OUTPUT_SUMS:
                tl.store(sums + row * n_chunks + gridx[None], curr_cumsum)
            cols += TILE
        if NORMALIZE:
            cols = gridx * t * TILE + tl.arange(0, TILE)
            for _ in range(0, t):
                cols_offset = cols * k_stride
                if HAS_OUT_LAYOUT:
                    cols_offset = cols * out_k_stride
                    row_offset = row * out_r_stride
                x = tl.load(out + row_offset + cols_offset, mask=cols < K, other=0)
                if x.dtype.is_fp16() | x.dtype.is_bf16():
                    x = x.to(tl.float32)
                x = x / curr_cumsum
                tl.store(out + row_offset + cols_offset, x, mask=cols < K)
                cols += TILE

def run_flaggems_block_cumsum_kernel_babcf48e(dev='cuda'):
    import torch
    inp = torch.randn((1,), device=dev, dtype=torch.float16)
    out = torch.randn((1,), device=dev, dtype=torch.float16)
    block_cumsum_kernel_babcf48e[(1, 1, 1)](inp, out, 0, 1, 1, 1, 1, 1, 1, 1, 1, OUTPUT_SUMS=False, NORMALIZE=True, HAS_OUT_LAYOUT=False, TILE=2048)
    return {'inp': inp, 'out': out}


