def block_update_kernel_c7685ef5(inp, base, rscale_ptr, out, r, t, R, K, r_stride, k_stride, out_r_stride, out_k_stride, rscale_stride, HAS_OUT_LAYOUT: tl.constexpr, TILE: tl.constexpr):
    gridx = ext_c7685ef5.program_id(0).to(tl.int64)
    gridy = ext_c7685ef5.program_id(1).to(tl.int64)
    n_gridx = ext_c7685ef5.num_programs(1)
    base += gridy * n_gridx + gridx
