    weight_x1 = tl.where(wx1 < 1.0, ((a + 2) * wx1 - (a + 3)) * wx1 * wx1 + 1, tl.where(wx1 < 2.0, ((wx1 - 5) * wx1 + 8) * wx1 * a - 4 * a, 0.0))
    dx2 = x0 + 2 - x
    wx2 = tl.abs(dx2)
    weight_x2 = tl.where(wx2 < 1.0, ((a + 2) * wx2 - (a + 3)) * wx2 * wx2 + 1, tl.where(wx2 < 2.0, ((wx2 - 5) * wx2 + 8) * wx2 * a - 4 * a, 0.0))
    dx3 = x0 + 3 - x
    wx3 = tl.abs(dx3)
    weight_x3 = tl.where(wx3 < 1.0, ((a + 2) * wx3 - (a + 3)) * wx3 * wx3 + 1, tl.where(wx3 < 2.0, ((wx3 - 5) * wx3 + 8) * wx3 * a - 4 * a, 0.0))
    dy0 = y0 - y
    wy0 = tl.abs(dy0)
    weight_y0 = tl.where(wy0 < 1.0, ((a + 2) * wy0 - (a + 3)) * wy0 * wy0 + 1, tl.where(wy0 < 2.0, ((wy0 - 5) * wy0 + 8) * wy0 * a - 4 * a, 0.0))
    dy1 = y0 + 1 - y
    wy1 = tl.abs(dy1)
    weight_y1 = tl.where(wy1 < 1.0, ((a + 2) * wy1 - (a + 3)) * wy1 * wy1 + 1, tl.where(wy1 < 2.0, ((wy1 - 5) * wy1 + 8) * wy1 * a - 4 * a, 0.0))
    dy2 = y0 + 2 - y
    wy2 = tl.abs(dy2)
    weight_y2 = tl.where(wy2 < 1.0, ((a + 2) * wy2 - (a + 3)) * wy2 * wy2 + 1, tl.where(wy2 < 2.0, ((wy2 - 5) * wy2 + 8) * wy2 * a - 4 * a, 0.0))
    dy3 = y0 + 3 - y
    wy3 = tl.abs(dy3)
    weight_y3 = tl.where(wy3 < 1.0, ((a + 2) * wy3 - (a + 3)) * wy3 * wy3 + 1, tl.where(wy3 < 2.0, ((wy3 - 5) * wy3 + 8) * wy3 * a - 4 * a, 0.0))
    input_base = n * C * H_in * W_in + c * H_in * W_in
    val = 0.0
    for i in range(4):
        y_idx = y0_int + i
        y_idx_clamped = tl.maximum(0, tl.minimum(y_idx, H_in - 1))
