    y = grid_y_refl_mod - 1.0
    if align_corners:
        x = (x + 1.0) * (W_in - 1) / 2.0
        y = (y + 1.0) * (H_in - 1) / 2.0
    else:
        x = (x + 1.0) * W_in / 2.0 - 0.5
        y = (y + 1.0) * H_in / 2.0 - 0.5
