    vals = tl.where(grid_x_nan | grid_y_nan | grid_z_nan, 0.0, vals_raw)
    output_base = n * C * D_out * H_out * W_out + c * D_out * H_out * W_out
    output_offsets = output_base + (d_out_3d * H_out * W_out + h_out_3d * W_out + w_out_3d)
