# ======================================================================
import flag_gems.utils.triton_lang_extension as tle_011e5e23

@triton.jit
def large_n_log_softmax_kernel_011e5e23(output_ptr, input_ptr, M, N, K, BLOCK_M: tl.constexpr=8, BLOCK_N: tl.constexpr=256):
    """Kernel for large N (N > 1024): two-pass online softmax algorithm."""
    pid_m = tle_011e5e23.program_id(0)
    pid_k = tle_011e5e23.program_id(1)
    m_offset = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    m = tl.full([BLOCK_M, BLOCK_N], value=float('-inf'), dtype=tl.float32)
    z = tl.full([BLOCK_M, BLOCK_N], value=0.0, dtype=tl.float32)
    for start_n in range(0, N, BLOCK_N):
        n_offset = start_n + tl.arange(0, BLOCK_N)
        offset = m_offset[:, None] * N * K + n_offset[None, :] * K + pid_k
        mask = (m_offset[:, None] < M) & (n_offset[None, :] < N)
        input_ptrs = input_ptr + offset
        inp = tl.load(input_ptrs, mask=mask, other=-float('inf')).to(tl.float32)
        m_new = tl.maximum(inp, m)
        all_neg_inf = m_new == float('-inf')
        z = tl.where(all_neg_inf, z, z * tl.exp(m - m_new) + tl.exp(inp - m_new))
        m = m_new
    m_reduced = tl.max(m, 1)
    z = tl.sum(z * tl.exp(m - m_reduced[:, None]), 1)
    m = m_reduced
    for start_n in range(0, N, BLOCK_N):
        n_offset = start_n + tl.arange(0, BLOCK_N)
        offset = m_offset[:, None] * N * K + n_offset[None, :] * K + pid_k
        mask = (m_offset[:, None] < M) & (n_offset[None, :] < N)
        input_ptrs = input_ptr + offset
        inp = tl.load(input_ptrs, mask=mask, other=-float('inf')).to(tl.float32)
        o = inp - m[:, None] - tl.log(z[:, None])
        tl.store(output_ptr + offset, o, mask=mask)

def run_flaggems_large_n_log_softmax_kernel_011e5e23(dev='cuda'):
    import torch
    output_ptr = torch.randn((1, 8192), device=dev, dtype=torch.float16)
    input_ptr = torch.randn((1, 8192), device=dev, dtype=torch.float16)
    large_n_log_softmax_kernel_011e5e23[(1, 1, 1)](output_ptr, input_ptr, 1, 8192, 1, BLOCK_M=8, BLOCK_N=256)
