def layer_norm_persistent_kernel_multiline_49666a40(in_ptr, out_ptr, weight_ptr, bias_ptr, out_mean_ptr, out_rstd_ptr, M, N, eps, TILE_M: tl.constexpr, TILE_N: tl.constexpr):
    pid = ext_49666a40.program_id(0)
    m_offsets = pid * TILE_M + tl.arange(0, TILE_M)
