    if bias_ptr is None:
        b = 0
    else:
        b = tl.load(bias_ptr + n_offsets, mask=n_mask)
    out = (x - m[:, None]) * rstd[:, None] * w + b
    tl.store(out_ptr + m_offsets[:, None] * N + n_offsets, out, mask=mask)

