@triton.jit
def median_small_dim_kernel_0f44d526(inp, values, indices, total_outputs, reduction_size, inner_size, BLOCK_N: tl.constexpr, BLOCK_OUT: tl.constexpr):
    out_offsets = tl.program_id(0) * BLOCK_OUT + tl.arange(0, BLOCK_OUT)
