# flaggems :: narrow_copy_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/narrow_copy.py#L11
# validated: OK in={'out_ptr': [1, 32, 64], 'inp_ptr': [16, 32, 64]} 0.279ms
# ======================================================================
@triton.jit
def narrow_copy_kernel_325c2faa(out_ptr, inp_ptr, total_elements, inp_total_elements, dim_size, dim_prod_post, start, length, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(0)
    block_start = pid * BLOCK_SIZE
    offsets = tl.arange(0, BLOCK_SIZE)
    mask = block_start + offsets < total_elements
    idx = block_start + offsets
    pre_idx = idx // (length * dim_prod_post)
    dim_idx = idx // dim_prod_post % length
    post_idx = idx % dim_prod_post
    inp_dim_idx = dim_idx + start
    inp_idx = pre_idx * dim_size * dim_prod_post + inp_dim_idx * dim_prod_post + post_idx
    inp_data = tl.load(inp_ptr + inp_idx, mask=mask)
    tl.store(out_ptr + idx, inp_data, mask=mask)

def run_flaggems_narrow_copy_kernel_325c2faa(dev='cuda'):
    import torch
    out_ptr = torch.randn((1, 32, 64), device=dev, dtype=torch.float16)
    inp_ptr = torch.randn((16, 32, 64), device=dev, dtype=torch.float16)
    narrow_copy_kernel_325c2faa[(2, 1, 1)](out_ptr, inp_ptr, 2048, 32768, 16, 2048, 0, 1, BLOCK_SIZE=1024)
    return {'out_ptr': out_ptr, 'inp_ptr': inp_ptr}


