# flaggems :: nonzero_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/nonzero.py#L15
# validated: OK in={'inp': [100], 'prefix_sum': [100], 'out': [100, 1], 'shape': [1]} 0.254ms
# ======================================================================
import flag_gems.utils.triton_lang_extension as ext_8b7c4708

@triton.jit
def nonzero_kernel_8b7c4708(inp, prefix_sum, out, n_elements, shape, ndim: tl.constexpr, BLOCK_SIZE: tl.constexpr):
    pid = ext_8b7c4708.program_id(0)
    offset = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offset < n_elements
    inp_vals = tl.load(inp + offset, mask=mask).to(tl.int1)
    out_offset = tl.load(prefix_sum + offset, mask=mask) - 1
    nonzero_mask = mask and inp_vals
    idx_flat = offset
    for dim in range(ndim - 1, -1, -1):
        dim_size = tl.load(shape + dim)
        remainder = idx_flat % dim_size
        idx_flat //= dim_size
        tl.store(out + out_offset * ndim + dim, remainder, mask=nonzero_mask)

def run_flaggems_nonzero_kernel_8b7c4708(dev='cuda'):
    import torch
    inp = torch.zeros((100,), device=dev, dtype=torch.bool)
    prefix_sum = torch.zeros((100,), device=dev, dtype=torch.int64)
    out = torch.zeros((100, 1), device=dev, dtype=torch.int64)
    shape = torch.zeros((1,), device=dev, dtype=torch.int32)
    nonzero_kernel_8b7c4708[(1, 1, 1)](inp, prefix_sum, out, 100, shape, ndim=1, BLOCK_SIZE=1024)
    return {'inp': inp, 'prefix_sum': prefix_sum, 'out': out, 'shape': shape}


