# flaggems :: one_hot_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/one_hot.py#L10
# validated: OK in={'index_ptr': [4], 'out_ptr': [4, 5]} 0.182ms
# ======================================================================
@triton.jit
def one_hot_kernel_1284cefc(index_ptr, out_ptr, num_classes, numel, BLOCK_M: tl.constexpr, BLOCK_N: tl.constexpr):
    pid = tl.program_id(0)
    row_start = pid * BLOCK_M
    row_offsets = row_start + tl.arange(0, BLOCK_M)
    row_mask = row_offsets < numel
    target_classes = tl.load(index_ptr + row_offsets, mask=row_mask, other=0)
    for col_st in range(0, num_classes, BLOCK_N):
        col_offsets = col_st + tl.arange(0, BLOCK_N)
        col_mask = col_offsets < num_classes
        result = target_classes[:, None] == col_offsets[None, :]
        result = result.to(tl.int64)
        offs_2d = row_offsets[:, None] * num_classes + col_offsets[None, :]
        tl.store(out_ptr + offs_2d, result, mask=row_mask[:, None] & col_mask[None, :])

def run_flaggems_one_hot_kernel_1284cefc(dev='cuda'):
    import torch
    index_ptr = torch.zeros((4,), device=dev, dtype=torch.int64)
    out_ptr = torch.zeros((4, 5), device=dev, dtype=torch.int64)
    one_hot_kernel_1284cefc[(1, 1, 1)](index_ptr, out_ptr, 5, 4, BLOCK_M=32, BLOCK_N=8)
    return {'index_ptr': index_ptr, 'out_ptr': out_ptr}


