# ======================================================================
import flag_gems.utils.triton_lang_extension as ext_c7e81fc2

@triton.jit
def ones_kernel_c7e81fc2(output_ptr, n_elements, BLOCK_SIZE: tl.constexpr):
    pid = ext_c7e81fc2.program_id(axis=0)
    block_start = pid * BLOCK_SIZE
    offsets = block_start + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    tl.store(output_ptr + offsets, 1.0, mask=mask)

def run_flaggems_ones_kernel_c7e81fc2(dev='cuda'):
    import torch
    output_ptr = torch.randn((8,), device=dev, dtype=torch.float16)
    ones_kernel_c7e81fc2[(1, 1, 1)](output_ptr, 8, BLOCK_SIZE=1024)
    return {'output_ptr': output_ptr}


