# validated: OK in={'idx_ptr': [1], 'counts_ptr': [1]} 0.2ms
# ======================================================================
import flag_gems.utils.triton_lang_extension as ext_6fe8ff3b

@triton.jit
def output_counts_flat_impl_6fe8ff3b(global_pid, idx_ptr: tl.tensor, origin_num_tasks: int, counts_ptr: tl.tensor, num_tasks: int, tile_size: tl.constexpr):
    r = tl.arange(0, tile_size)
    i0 = global_pid * tile_size + r
    mask = i0 < num_tasks
    idx = tl.load(idx_ptr + i0, mask=mask)
    i0_next = i0 + 1
    next_mask = i0_next < num_tasks
    idx_next = tl.load(idx_ptr + i0_next, mask=next_mask)
    counts = tl.where(i0_next < num_tasks, idx_next - idx, origin_num_tasks - idx)
    tl.store(counts_ptr + i0, counts, mask=mask)

@triton.jit
def output_counts_flat_kernel_6fe8ff3b(idx_ptr: tl.tensor, origin_num_tasks: int, counts_ptr: tl.tensor, num_tasks: int, tiles_per_cta: int, tile_size: tl.constexpr):
    pid = ext_6fe8ff3b.program_id(0)
    ctas_num = ext_6fe8ff3b.num_programs(0)
    for j in range(0, tiles_per_cta):
        global_pid = pid + j * ctas_num
        output_counts_flat_impl_6fe8ff3b(global_pid, idx_ptr, origin_num_tasks, counts_ptr, num_tasks, tile_size)

def run_flaggems_output_counts_flat_kernel_6fe8ff3b(dev='cuda'):
    import torch
    idx_ptr = torch.zeros((1,), device=dev, dtype=torch.int64)
    counts_ptr = torch.zeros((1,), device=dev, dtype=torch.int64)
    output_counts_flat_kernel_6fe8ff3b[(1, 1, 1)](idx_ptr, 1, counts_ptr, 1, 1, tile_size=1)
    return {'idx_ptr': idx_ptr, 'counts_ptr': counts_ptr}


