# flaggems :: pixel_shuffle_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/pixel_shuffle.py#L16
# validated: OK in={'in_ptr': [1, 12, 4, 4], 'out_ptr': [1, 3, 8, 8]} 0.239ms
# ======================================================================
@triton.jit
def pixel_shuffle_kernel_0820dc02(in_ptr, out_ptr, n_elements, C, H, W, R, C_out, H_out, W_out, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    ow = offsets % W_out
    tmp = offsets // W_out
    oh = tmp % H_out
    tmp2 = tmp // H_out
    c_out = tmp2 % C_out
    n = tmp2 // C_out
    h_in = oh // R
    dh = oh % R
    w_in = ow // R
    dw = ow % R
    c_in = c_out * R * R + dh * R + dw
    in_idx = n * (C * H * W) + c_in * (H * W) + h_in * W + w_in
    val = tl.load(in_ptr + in_idx, mask=mask)
    tl.store(out_ptr + offsets, val, mask=mask)

def run_flaggems_pixel_shuffle_kernel_0820dc02(dev='cuda'):
    import torch
    in_ptr = torch.randn((1, 12, 4, 4), device=dev, dtype=torch.float16)
    out_ptr = torch.randn((1, 3, 8, 8), device=dev, dtype=torch.float16)
    pixel_shuffle_kernel_0820dc02[(1, 1, 1)](in_ptr, out_ptr, 192, 12, 4, 4, 2, 3, 8, 8, BLOCK_SIZE=256)
    return {'in_ptr': in_ptr, 'out_ptr': out_ptr}


