# flaggems :: pixel_unshuffle_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/pixel_unshuffle.py#L13
# validated: OK in={'in_ptr': [1, 3, 8, 8], 'out_ptr': [1, 12, 4, 4]} 0.204ms
# ======================================================================
@triton.jit
def pixel_unshuffle_kernel_4e20b588(in_ptr, out_ptr, n_elements, N, C, H, W, R, C_out, H_out, W_out, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(axis=0)
    block_start = pid * BLOCK_SIZE
    offsets = block_start + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    sN_in = C * H * W
    sC_in = H * W
    sH_in = W
    sW_in = 1
    sN_out = C_out * H_out * W_out
    sC_out = H_out * W_out
    sH_out = W_out
    sW_out = 1
    n = offsets // sN_out
    rem1 = offsets - n * sN_out
    c_out = rem1 // sC_out
    rem2 = rem1 - c_out * sC_out
    h_out = rem2 // sH_out
    w_out = rem2 - h_out * sH_out
    r2 = R * R
    c_in = c_out // r2
    remc = c_out - c_in * r2
    dh = remc // R
    dw = remc - dh * R
    h_in = h_out * R + dh
    w_in = w_out * R + dw
    in_index = n * sN_in + c_in * sC_in + h_in * sH_in + w_in * sW_in
    x = tl.load(in_ptr + in_index, mask=mask)
    tl.store(out_ptr + offsets, x, mask=mask)

def run_flaggems_pixel_unshuffle_kernel_4e20b588(dev='cuda'):
    import torch
    in_ptr = torch.randn((1, 3, 8, 8), device=dev, dtype=torch.float16)
    out_ptr = torch.randn((1, 12, 4, 4), device=dev, dtype=torch.float16)
    pixel_unshuffle_kernel_4e20b588[(1, 1, 1)](in_ptr, out_ptr, 192, 1, 3, 8, 8, 2, 12, 4, 4, BLOCK_SIZE=1024)
    return {'in_ptr': in_ptr, 'out_ptr': out_ptr}


