# flaggems :: poisson_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/poisson.py#L85
# NOT runnable (not-runnable): TypeError: 'function' object is not subscriptable
# ======================================================================
@triton.jit
def poisson_inverse_2061848d(lam, lam_bound, seed, c0, c1, z, CAP: tl.constexpr):
    """Inverse-transform sampling: one uniform, accumulate CDF until s >= u."""
    r0, r1, r2, r3 = tl.philox(seed, c0, c1, z, z)
    u = uint_to_uniform_float(r0)
    p = tl.exp(-lam)
    s = p
    k = (lam * 0).to(tl.int32)
    iters = tl.minimum((lam_bound + 2.5 * tl.sqrt(lam_bound) + 2.0).to(tl.int32), CAP)
    iters = tl.maximum(iters, 1)
    for _ in tl.range(0, iters):
        active = u > s
        k = tl.where(active, k + 1, k)
        denom = tl.where(active, k.to(tl.float32), 1.0)
        p = tl.where(active, p * lam / denom, p)
        s = tl.where(active, s + p, s)
    return k.to(tl.float32)

@triton.jit
def high_precision_fast_sin_cos_2061848d(x):
    two_pi = 6.283185307179586
    x = x - two_pi * tl.floor(x / two_pi + 0.5)
    x2 = x * x
    s_c0 = 1.0
    s_c1 = -0.16666666666666666
    s_c2 = 0.008333333333333328
    s_c3 = -0.00019841269841269616
    s_c4 = 2.755731922398589e-06
    s_c5 = -2.505210838544172e-08
    sin_x = x * (s_c0 + x2 * (s_c1 + x2 * (s_c2 + x2 * (s_c3 + x2 * (s_c4 + x2 * s_c5)))))
    c_c0 = 1.0
    c_c1 = -0.5
    c_c2 = 0.041666666666666664
    c_c3 = -0.0013888888888888874
    c_c4 = 2.4801587301587298e-05
    c_c5 = -2.755731922398581e-07
    cos_x = c_c0 + x2 * (c_c1 + x2 * (c_c2 + x2 * (c_c3 + x2 * (c_c4 + x2 * c_c5))))
    return (sin_x, cos_x)

@triton.jit
def poisson_corrected_normal_2061848d(lam, seed, c0, c1, z):
    """Normal approximation with alpha^2/6 skewness correction (Box-Muller)."""
    r0, r1, r2, r3 = tl.philox(seed, c0, c1, z, z)
    u1 = tl.maximum(uint_to_uniform_float(r0), 1e-10)
    u2 = uint_to_uniform_float(r1)
    radius = tl.sqrt(-2.0 * tl.log(u1))
    _, cos_t = high_precision_fast_sin_cos_2061848d(6.283185307179586 * u2)
    alpha = radius * cos_t
    y = lam + alpha * tl.sqrt(lam) + alpha * alpha / 6.0
    return tl.floor(tl.maximum(y, 0.0) + 0.5)

def poisson_kernel_2061848d(inp_ptr, out_ptr, N, philox_seed, philox_offset, BLOCK: tl.constexpr, CAP: tl.constexpr, STRIDE: tl.constexpr, IMAX: tl.constexpr):
    philox_seed = philox_seed.to(tl.int64)
    philox_offset = philox_offset.to(tl.int64)
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < N
    lam = tl.maximum(tl.load(inp_ptr + offs, mask=mask, other=0.0).to(tl.float32), 0.0)
    bmax = tl.max(lam)
    counter = philox_offset + offs.to(tl.int64) * STRIDE
    c0 = (counter & 4294967295).to(tl.uint32)
    c1 = (counter >> 32 & 4294967295).to(tl.uint32)
    z = c0 * 0
    if bmax <= IMAX:
        result = poisson_inverse_2061848d(lam, bmax, philox_seed, c0, c1, z, CAP)
    else:
        inv = poisson_inverse_2061848d(lam, IMAX * 1.0, philox_seed, c0, c1, z, CAP)
        nrm = poisson_corrected_normal_2061848d(lam, philox_seed, c0, c1, z)
        result = tl.where(lam <= IMAX, inv, nrm)
    tl.store(out_ptr + offs, result, mask=mask)

def run_flaggems_poisson_kernel_2061848d(dev='cuda'):
    import torch
    inp_ptr = torch.randn((20, 320, 15), device=dev, dtype=torch.float16)
    out_ptr = torch.randn((20, 320, 15), device=dev, dtype=torch.float16)
    poisson_kernel_2061848d[(47, 1, 1)](inp_ptr, out_ptr, 96000, 0, 36372, BLOCK=2048, CAP=48, STRIDE=8, IMAX=20.0)
    return {'inp_ptr': inp_ptr, 'out_ptr': out_ptr}


