@triton.jit
def prelu_kernel_e0bd406b(x_ptr, w_ptr, out_ptr, n_elements, S, C, w_is_scalar: tl.constexpr, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(axis=0)
    block_start = pid * BLOCK_SIZE
    offsets = block_start + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    x = tl.load(x_ptr + offsets, mask=mask)
    if w_is_scalar:
        alpha = tl.load(w_ptr)
        y = tl.where(x >= 0, x, alpha * x)
    else:
        c = offsets // S % C
        alpha = tl.load(w_ptr + c, mask=mask)
        y = tl.where(x >= 0, x, alpha * x)
    tl.store(out_ptr + offsets, y, mask=mask)

def run_flaggems_prelu_kernel_e0bd406b(dev='cuda'):
    import torch
    x_ptr = torch.randn((2, 3), device=dev, dtype=torch.float16)
