    off0 = start + tl.arange(0, BLOCK)
    off1 = off0 + BLOCK
    off2 = off1 + BLOCK
    off3 = off2 + BLOCK
    tl.store(out_ptr + off0, r0_mod, mask=off0 < N)
    tl.store(out_ptr + off1, r1_mod, mask=off1 < N)
    tl.store(out_ptr + off2, r2_mod, mask=off2 < N)
    tl.store(out_ptr + off3, r3_mod, mask=off3 < N)

