# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/reflection_pad1d.py#L14
# validated: OK in={'in_ptr': [3, 33], 'out_ptr': [3, 35]} 2.436ms
# ======================================================================
@triton.jit
def reflection_pad1d_kernel_25c0868e(in_ptr, out_ptr, B, W_in, pad_left, W_out, BLOCK_W: tl.constexpr):
    pid_b = tl.program_id(axis=0)
    pid_w = tl.program_id(axis=1)
    offs_w = pid_w * BLOCK_W + tl.arange(0, BLOCK_W)
    mask = (offs_w < W_out) & (pid_b < B)
    base_in = pid_b * W_in
    base_out = pid_b * W_out
    x = offs_w.to(tl.int32) - pad_left
    Wm1 = W_in - 1
    p = 2 * Wm1
    t = tl.abs(x)
    m = t % p
    iw = tl.where(m < W_in, m, p - m)
    vals = tl.load(in_ptr + base_in + iw, mask=mask, other=0)
    tl.store(out_ptr + base_out + offs_w, vals, mask=mask)

def run_flaggems_reflection_pad1d_kernel_25c0868e(dev='cuda'):
    import torch
    in_ptr = torch.randn((3, 33), device=dev, dtype=torch.float16)
    out_ptr = torch.randn((3, 35), device=dev, dtype=torch.float16)
    reflection_pad1d_kernel_25c0868e[(3, 1, 1)](in_ptr, out_ptr, 3, 33, 1, 35, BLOCK_W=256)
    return {'in_ptr': in_ptr, 'out_ptr': out_ptr}


