def rms_norm_loop_kernel_8e8a24da(out_ptr, INV_RMS, in_ptr, w_ptr, N, eps, TILE_N: tl.constexpr):
    if tl.constexpr(in_ptr.dtype.element_ty == tl.float16) or tl.constexpr(in_ptr.dtype.element_ty == tl.bfloat16):
        cdtype = tl.float32
    else:
        cdtype = in_ptr.dtype.element_ty
    pid = ext_8e8a24da.program_id(0)
