@triton.jit
def round_half_to_even_impl_5b9eeea3(x):
    """Round to nearest with ties to even (round half to even).
    x must be fp32."""
    r = tl.floor(x)
    d = x - r
    is_odd = tl.abs(r - 2.0 * tl.floor(r / 2.0)) > 0.5
    return tl.where((d > 0.5) | (tl.abs(d - 0.5) < 1e-10) & is_odd, r + 1.0, r)

@triton.jit
def round_kernel_5b9eeea3(x_ptr, out_ptr, n_elements, decimals: tl.constexpr, BLOCK_SIZE: tl.constexpr, IS_FP32: tl.constexpr, IS_FP16: tl.constexpr, IS_BF16: tl.constexpr):
    pid = tl.program_id(axis=0)
    block_start = pid * BLOCK_SIZE
    offsets = block_start + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    x = tl.load(x_ptr + offsets, mask=mask)
    if decimals == 0:
        out = x
        if IS_FP32:
            out = round_half_to_even_impl_5b9eeea3(x)
        elif IS_FP16:
            x_fp32 = tl.cast(x, tl.float32)
            out = tl.cast(round_half_to_even_impl_5b9eeea3(x_fp32), tl.float16)
        elif IS_BF16:
            x_fp32 = tl.cast(x, tl.float32)
            out = tl.cast(round_half_to_even_impl_5b9eeea3(x_fp32), tl.bfloat16)
    else:
        scale = 10.0 ** decimals
        if IS_FP32:
            x_scaled = x * scale
            out = round_half_to_even_impl_5b9eeea3(x_scaled) / scale
        elif IS_FP16:
            x_fp32 = tl.cast(x, tl.float32)
            x_scaled = x_fp32 * scale
            out = tl.cast(round_half_to_even_impl_5b9eeea3(x_scaled) / scale, tl.float16)
        elif IS_BF16:
            x_fp32 = tl.cast(x, tl.float32)
            x_scaled = x_fp32 * scale
            out = tl.cast(round_half_to_even_impl_5b9eeea3(x_scaled) / scale, tl.bfloat16)
        else:
            out = x
    tl.store(out_ptr + offsets, out, mask=mask)

