# validated: OK in={'out_ptr': [1, 1024], 'inp_ptr': [1, 1024], 'src_ptr': [1, 1024]} 0.248ms
# ======================================================================
@triton.jit
def slice_scatter_kernel_c9a0d916(out_ptr, inp_ptr, src_ptr, total_elements, dim_size, dim_prod_post, start, step, src_dim_size, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(0)
    block_start = pid * BLOCK_SIZE
    offsets = tl.arange(0, BLOCK_SIZE)
    mask = block_start + offsets < total_elements
    idx = block_start + offsets
    pre_idx = idx // (dim_size * dim_prod_post)
    dim_idx = idx // dim_prod_post % dim_size
    post_idx = idx % dim_prod_post
    slice_mask = (dim_idx >= start) & (dim_idx < start + src_dim_size * step) & ((dim_idx - start) % step == 0)
    inp_data = tl.load(inp_ptr + idx, mask=mask)
    src_dim_idx = (dim_idx - start) // step
    src_idx = pre_idx * src_dim_size * dim_prod_post + src_dim_idx * dim_prod_post + post_idx
    src_data = tl.load(src_ptr + src_idx, mask=mask & slice_mask)
    result = tl.where(slice_mask, src_data, inp_data)
    tl.store(out_ptr + idx, result, mask=mask)

def run_flaggems_slice_scatter_kernel_c9a0d916(dev='cuda'):
    import torch
    out_ptr = torch.randn((1, 1024), device=dev, dtype=torch.float16)
    inp_ptr = torch.randn((1, 1024), device=dev, dtype=torch.float16)
    src_ptr = torch.randn((1, 1024), device=dev, dtype=torch.float16)
    slice_scatter_kernel_c9a0d916[(1, 1, 1)](out_ptr, inp_ptr, src_ptr, 1024, 1, 1024, 0, 1, 1, BLOCK_SIZE=1024)
    return {'out_ptr': out_ptr, 'inp_ptr': inp_ptr, 'src_ptr': src_ptr}


# ======================================================================
# flaggems :: small_n_log_softmax_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/special_log_softmax.py#L30
# validated: OK in={'output_ptr': [32, 64], 'input_ptr': [32, 64]} 0.258ms
# ======================================================================
@triton.jit
def small_n_log_softmax_kernel_e25f0c15(output_ptr, input_ptr, M, N, stride_m, BLOCK_N: tl.constexpr):
    """Kernel for small N (N <= 1024): single warp, single pass scan."""
    row_id = tl.program_id(0)
    col_offsets = tl.arange(0, BLOCK_N)
    mask = col_offsets < N
    row = tl.load(input_ptr + row_id * stride_m + col_offsets, mask=mask, other=-float('inf')).to(tl.float32)
    row_max = tl.max(row, axis=0)
    row_shifted = row - row_max
    exp_row = tl.exp(row_shifted)
    sum_exp = tl.sum(exp_row, axis=0)
    log_sum = tl.log(sum_exp)
    out = row_shifted - log_sum
    tl.store(output_ptr + row_id * stride_m + col_offsets, out, mask=mask)

def run_flaggems_small_n_log_softmax_kernel_e25f0c15(dev='cuda'):
    import torch
    output_ptr = torch.randn((32, 64), device=dev, dtype=torch.float16)
    input_ptr = torch.randn((32, 64), device=dev, dtype=torch.float16)
    small_n_log_softmax_kernel_e25f0c15[(32, 1, 1)](output_ptr, input_ptr, 32, 64, 64, BLOCK_N=64)
    return {'output_ptr': output_ptr, 'input_ptr': input_ptr}


