import flag_gems.utils.triton_lang_extension as ext_eb3b8d9a

@triton.jit
def softmax_backward_kernel_inner_eb3b8d9a(out_ptr, out_grad_ptr, in_grad_ptr, M, N, TILE_M: tl.constexpr, TILE_N: tl.constexpr, ONE_TILE_PER_CTA: tl.constexpr):
    pid_m = ext_eb3b8d9a.program_id(0)
    m_offsets = pid_m * TILE_M + tl.arange(0, TILE_M)
    if ONE_TILE_PER_CTA:
        n_offsets = tl.arange(0, TILE_N)
        offsets = m_offsets[:, None] * N + n_offsets
        mask = (m_offsets[:, None] < M) & (n_offsets < N)
        out_tile = tl.load(out_ptr + offsets, mask=mask).to(tl.float32)
        out_grad_tile = tl.load(out_grad_ptr + offsets, mask=mask).to(tl.float32)
        scale = tl.sum(out_tile * out_grad_tile, 1)
        in_grad_tile = out_tile * (out_grad_tile - scale[:, None])
        tl.store(in_grad_ptr + offsets, in_grad_tile, mask=mask)
    else:
        scale = tl.zeros([TILE_M, TILE_N], dtype=tl.float32)
        n_offsets = tl.arange(0, TILE_N)
        offsets = m_offsets[:, None] * N + n_offsets
        for _ in range(0, N, TILE_N):
            mask = (m_offsets[:, None] < M) & (n_offsets < N)
            out_tile = tl.load(out_ptr + offsets, mask=mask, eviction_policy='evict_last').to(tl.float32)
            out_grad_tile = tl.load(out_grad_ptr + offsets, mask=mask).to(tl.float32)
            scale += out_tile * out_grad_tile
            n_offsets += TILE_N
            offsets += TILE_N
        scale = tl.sum(scale, 1)
        n_offsets = tl.arange(0, TILE_N)
        offsets = m_offsets[:, None] * N + n_offsets
        for _ in range(0, N, TILE_N):
            mask = (m_offsets[:, None] < M) & (n_offsets < N)
            out_tile = tl.load(out_ptr + offsets, mask=mask, eviction_policy='evict_first').to(tl.float32)
            out_grad_tile = tl.load(out_grad_ptr + offsets, mask=mask).to(tl.float32)
            in_grad_tile = out_tile * (out_grad_tile - scale[:, None])
            tl.store(in_grad_ptr + offsets, in_grad_tile, mask=mask)
            n_offsets += TILE_N
            offsets += TILE_N

def run_flaggems_softmax_backward_kernel_inner_eb3b8d9a(dev='cuda'):
    import torch
    out_ptr = torch.randn((1, 256), device=dev, dtype=torch.float16)
    out_grad_ptr = torch.randn((1, 256), device=dev, dtype=torch.float16)
    in_grad_ptr = torch.randn((1, 256), device=dev, dtype=torch.float16)
    softmax_backward_kernel_inner_eb3b8d9a[(1, 1, 1)](out_ptr, out_grad_ptr, in_grad_ptr, 1, 256, TILE_M=32, TILE_N=32, ONE_TILE_PER_CTA=False)
    return {'out_ptr': out_ptr, 'out_grad_ptr': out_grad_ptr, 'in_grad_ptr': in_grad_ptr}


