# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/softmax.py#L88
# validated: OK in={'output_ptr': [1, 256], 'input_ptr': [1, 256]} 0.225ms
# ======================================================================
import flag_gems.utils.triton_lang_extension as ext_0519f4c8

@triton.jit
def prev_multiple_of_0519f4c8(a, b):
    return tl.cdiv(a, b) * b - b

@triton.jit
def softmax_kernel_inner_0519f4c8(output_ptr, input_ptr, M, N, TILE_N: tl.constexpr, ONE_TILE_PER_CTA: tl.constexpr):
    pid_m = ext_0519f4c8.program_id(0)
    if ONE_TILE_PER_CTA:
        n_offsets = tl.arange(0, TILE_N)
        offset = pid_m * N + n_offsets
        input_ptrs = input_ptr + offset
        mask = n_offsets < N
        inp = tl.load(input_ptrs, mask=mask, other=-float('inf')).to(output_ptr.dtype.element_ty)
        m = tl.max(inp, 0)
        e = tl.exp(inp - m)
        z = tl.sum(e, 0)
        out = e / z
        output_ptrs = output_ptr + offset
        tl.store(output_ptrs, out, mask=mask)
    else:
        m = tl.full([TILE_N], value=float('-inf'), dtype=tl.float32)
        z = tl.full([TILE_N], value=0.0, dtype=tl.float32)
        input_ptr += pid_m * N
        output_ptr += pid_m * N
        previous_multiple = prev_multiple_of_0519f4c8(N, TILE_N)
        for start_n in range(0, previous_multiple, TILE_N):
            n_offsets = start_n + tl.arange(0, TILE_N)
            inp = tl.load(input_ptr + n_offsets)
            m_new = tl.maximum(m, inp)
            all_neg_inf = m_new == float('-inf')
            z = tl.where(all_neg_inf, z, z * tl.exp(m - m_new) + tl.exp(inp - m_new))
            m = m_new
        for start_n in range(previous_multiple, N, TILE_N):
            n_offsets = start_n + tl.arange(0, TILE_N)
            mask = n_offsets < N
            inp = tl.load(input_ptr + n_offsets, mask=mask, other=-float('inf'))
            m_new = tl.maximum(m, inp)
            all_neg_inf = m_new == float('-inf')
            z = tl.where(all_neg_inf, z, z * tl.exp(m - m_new) + tl.exp(inp - m_new))
            m = m_new
        m_reduced = tl.max(m, 0)
        z = tl.sum(z * tl.exp(m - m_reduced), 0)
        m = m_reduced
        previous_multiple = prev_multiple_of_0519f4c8(N, TILE_N)
        for start_n in range(0, TILE_N, TILE_N):
            n_offsets = previous_multiple - start_n + tl.arange(0, TILE_N)
            mask = n_offsets < N
            inp = tl.load(input_ptr + n_offsets, mask=mask, other=-float('inf'), eviction_policy='evict_first')
            o = tl.exp(inp - m) / z
            tl.store(output_ptr + n_offsets, o, mask=mask)
        for start_n in range(TILE_N, N, TILE_N):
            n_offsets = previous_multiple - start_n + tl.arange(0, TILE_N)
            inp = tl.load(input_ptr + n_offsets, eviction_policy='evict_first')
            o = tl.exp(inp - m) / z
            tl.store(output_ptr + n_offsets, o)

def run_flaggems_softmax_kernel_inner_0519f4c8(dev='cuda'):
    import torch
    output_ptr = torch.randn((1, 256), device=dev, dtype=torch.float16)
    input_ptr = torch.randn((1, 256), device=dev, dtype=torch.float16)
    softmax_kernel_inner_0519f4c8[(1, 1, 1)](output_ptr, input_ptr, 1, 256, TILE_N=256, ONE_TILE_PER_CTA=True)
    return {'output_ptr': output_ptr, 'input_ptr': input_ptr}


