# flaggems :: softshrink_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/softshrink.py#L9
# validated: OK in={'x_ptr': [], 'out_ptr': []} 0.238ms
# ======================================================================
@triton.jit
def softshrink_kernel_0b75aabb(x_ptr, out_ptr, n_elements, lambd, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(axis=0)
    block_start = pid * BLOCK_SIZE
    offsets = block_start + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    x = tl.load(x_ptr + offsets, mask=mask, other=0)
    x32 = x.to(tl.float32)
    threshold = lambd
    gt = x32 > threshold
    lt = x32 < -threshold
    res32 = tl.where(gt, x32 - threshold, tl.where(lt, x32 + threshold, 0.0))
    res32 = tl.where(x32 != x32, x32, res32)
    res = res32.to(x.dtype)
    tl.store(out_ptr + offsets, res, mask=mask)

def run_flaggems_softshrink_kernel_0b75aabb(dev='cuda'):
    import torch
    x_ptr = torch.randn((), device=dev, dtype=torch.float16)
    out_ptr = torch.randn((), device=dev, dtype=torch.float16)
    softshrink_kernel_0b75aabb[(1, 1, 1)](x_ptr, out_ptr, 1, 0.5, BLOCK_SIZE=1024)
    return {'x_ptr': x_ptr, 'out_ptr': out_ptr}


