import flag_gems.utils.triton_lang_extension as tle_d23446af

@triton.jit
def sparse_semi_structured_mm_kernel_d23446af(A, Meta, B, C, M, N, K4, stride_am, stride_ak, stride_mm, stride_mn, stride_bk, stride_bn, stride_cm, stride_cn, BLOCK_SIZE_M: tl.constexpr, BLOCK_SIZE_N: tl.constexpr, BLOCK_SIZE_K: tl.constexpr):
    """
    Kernel for sparse semi-structured matrix multiplication.

    A: (M, 4*K4) - dense matrix with 2:4 sparsity pattern
    Meta: (M, K4) - boolean mask indicating which 2 elements in each group of 4 are valid
    B: (4*K4, N) - dense matrix
    C: (M, N) - output matrix

    For each group of 4 elements in A's K dimension:
    - Meta[i, k] = True: use A[i, 4k] and A[i, 4k+1]
    - Meta[i, k] = False: use A[i, 4k+2] and A[i, 4k+3]
    """
    pid = tle_d23446af.program_id(0)
    num_pid_n = tl.cdiv(N, BLOCK_SIZE_N)
    pid_m = pid // num_pid_n
    pid_n = pid % num_pid_n
    offs_am = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M)
    offs_bn = pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N)
    offs_k = tl.arange(0, BLOCK_SIZE_K)
    K = K4 * 4
    accumulator = tl.zeros((BLOCK_SIZE_M, BLOCK_SIZE_N), dtype=tl.float32)
    num_iters = tl.cdiv(K4, BLOCK_SIZE_K)
    for k in range(num_iters):
        k_offset = k * BLOCK_SIZE_K
        meta_ptrs = Meta + (offs_am[:, None] * stride_mm + (offs_k + k_offset)[None, :] * stride_mn)
        mask_2d = offs_am[:, None] < M
        mask_2d = mask_2d & ((offs_k + k_offset)[None, :] < K4)
        meta = tl.load(meta_ptrs, mask=mask_2d, other=0)
        a0_ptrs = A + (offs_am[:, None] * stride_am + (offs_k * 4 + k_offset * 4 + 0)[None, :] * stride_ak)
        mask_a = (offs_am[:, None] < M) & ((offs_k * 4 + k_offset * 4 + 0)[None, :] < K)
        a0 = tl.load(a0_ptrs, mask=mask_a, other=0.0)
        a1_ptrs = A + (offs_am[:, None] * stride_am + (offs_k * 4 + k_offset * 4 + 1)[None, :] * stride_ak)
        mask_a = (offs_am[:, None] < M) & ((offs_k * 4 + k_offset * 4 + 1)[None, :] < K)
        a1 = tl.load(a1_ptrs, mask=mask_a, other=0.0)
        a2_ptrs = A + (offs_am[:, None] * stride_am + (offs_k * 4 + k_offset * 4 + 2)[None, :] * stride_ak)
        mask_a = (offs_am[:, None] < M) & ((offs_k * 4 + k_offset * 4 + 2)[None, :] < K)
        a2 = tl.load(a2_ptrs, mask=mask_a, other=0.0)
        a3_ptrs = A + (offs_am[:, None] * stride_am + (offs_k * 4 + k_offset * 4 + 3)[None, :] * stride_ak)
        mask_a = (offs_am[:, None] < M) & ((offs_k * 4 + k_offset * 4 + 3)[None, :] < K)
        a3 = tl.load(a3_ptrs, mask=mask_a, other=0.0)
        b0_ptrs = B + ((offs_k * 4 + k_offset * 4 + 0)[:, None] * stride_bk + offs_bn[None, :] * stride_bn)
        mask_b = ((offs_k * 4 + k_offset * 4 + 0)[:, None] < K) & (offs_bn[None, :] < N)
        b0 = tl.load(b0_ptrs, mask=mask_b, other=0.0)
        b1_ptrs = B + ((offs_k * 4 + k_offset * 4 + 1)[:, None] * stride_bk + offs_bn[None, :] * stride_bn)
        mask_b = ((offs_k * 4 + k_offset * 4 + 1)[:, None] < K) & (offs_bn[None, :] < N)
        b1 = tl.load(b1_ptrs, mask=mask_b, other=0.0)
        b2_ptrs = B + ((offs_k * 4 + k_offset * 4 + 2)[:, None] * stride_bk + offs_bn[None, :] * stride_bn)
        mask_b = ((offs_k * 4 + k_offset * 4 + 2)[:, None] < K) & (offs_bn[None, :] < N)
        b2 = tl.load(b2_ptrs, mask=mask_b, other=0.0)
        b3_ptrs = B + ((offs_k * 4 + k_offset * 4 + 3)[:, None] * stride_bk + offs_bn[None, :] * stride_bn)
        mask_b = ((offs_k * 4 + k_offset * 4 + 3)[:, None] < K) & (offs_bn[None, :] < N)
        b3 = tl.load(b3_ptrs, mask=mask_b, other=0.0)
        meta_exp = meta[:, :, None]
        prod00_exp = a0[:, :, None] * b0[None, :, :]
        prod01_exp = a1[:, :, None] * b1[None, :, :]
        prod02_exp = a2[:, :, None] * b2[None, :, :]
        prod03_exp = a3[:, :, None] * b3[None, :, :]
        selected = (prod00_exp + prod01_exp) * meta_exp + (prod02_exp + prod03_exp) * (1 - meta_exp)
        accumulator += tl.sum(selected, axis=1)
    c_ptrs = C + stride_cm * offs_am[:, None] + stride_cn * offs_bn[None, :]
    c_mask = (offs_am[:, None] < M) & (offs_bn[None, :] < N)
    tl.store(c_ptrs, accumulator, mask=c_mask)

def run_flaggems_sparse_semi_structured_mm_kernel_d23446af(dev='cuda'):
    import torch
    A = torch.randn((64, 128), device=dev, dtype=torch.float16)
    Meta = torch.zeros((64, 32), device=dev, dtype=torch.bool)
    B = torch.randn((128, 64), device=dev, dtype=torch.float16)
    C = torch.randn((64, 64), device=dev, dtype=torch.float16)
    sparse_semi_structured_mm_kernel_d23446af[(4, 1, 1)](A, Meta, B, C, 64, 64, 32, 128, 1, 32, 1, 64, 1, 64, 1, BLOCK_SIZE_M=32, BLOCK_SIZE_N=32, BLOCK_SIZE_K=32)
    return {'A': A, 'Meta': Meta, 'B': B, 'C': C}


