# flaggems :: special_i1_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/special_i1.py#L14
# validated: OK in={'x_ptr': [], 'out_ptr': []} 0.249ms
# ======================================================================
@triton.jit
def special_i1_kernel_7e502f07(x_ptr, out_ptr, n_elements, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(axis=0)
    block_start = pid * BLOCK_SIZE
    offsets = block_start + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    x = tl.load(x_ptr + offsets, mask=mask, other=0.0)
    x_f32 = x.to(tl.float32)
    ax = tl.abs(x_f32)
    y = x_f32 / 3.75
    y2 = y * y
    p = 0.00032411
    p = 0.00301532 + y2 * p
    p = 0.02658733 + y2 * p
    p = 0.15084934 + y2 * p
    p = 0.51498869 + y2 * p
    p = 0.87890594 + y2 * p
    p = 0.5 + y2 * p
    ans_small = x_f32 * p
    t = 3.75 / tl.maximum(ax, 1e-20)
    q = -0.00420059
    q = 0.01787654 + t * q
    q = -0.02895312 + t * q
    q = 0.02282967 + t * q
    q = -0.01031555 + t * q
    q = 0.00163801 + t * q
    q = -0.00362018 + t * q
    q = -0.03988024 + t * q
    q = 0.39894228 + t * q
    pref = tl.exp(ax) / tl.sqrt(tl.maximum(ax, 1e-20))
    ans_large = pref * q
    ans_large = tl.where(x_f32 < 0, -ans_large, ans_large)
    is_small = ax <= 3.75
    ans = tl.where(is_small, ans_small, ans_large)
    tl.store(out_ptr + offsets, ans.to(x.dtype), mask=mask)

def run_flaggems_special_i1_kernel_7e502f07(dev='cuda'):
    import torch
    x_ptr = torch.randn((), device=dev, dtype=torch.float16)
    out_ptr = torch.randn((), device=dev, dtype=torch.float16)
    special_i1_kernel_7e502f07[(1, 1, 1)](x_ptr, out_ptr, 1, BLOCK_SIZE=1024)
    return {'x_ptr': x_ptr, 'out_ptr': out_ptr}


