# flaggems :: trace_kernel
# src: https://github.com/FlagOpen/FlagGems/blob/c079c4bb245db2b4cf8956eae93bed7c66ce9d6d/src/flag_gems/ops/trace.py#L13
# validated: OK in={'inp_ptr': [1, 1], 'out_ptr': []} 0.26ms
# ======================================================================
@triton.jit
def trace_kernel_8775e945(inp_ptr, out_ptr, num_diag, stride0, stride1, BLOCK_SIZE: tl.constexpr):
    inp_dtype = inp_ptr.type.element_ty
    if inp_dtype.is_int():
        acc_dtype = tl.int64
        other_val = 0
    elif inp_dtype == tl.float64:
        acc_dtype = tl.float64
        other_val = 0.0
    else:
        acc_dtype = tl.float32
        other_val = 0.0
    acc = tl.zeros((BLOCK_SIZE,), dtype=acc_dtype)
    diag_stride = stride0 + stride1
    for i in range(0, tl.cdiv(num_diag, BLOCK_SIZE)):
        block_start = i * BLOCK_SIZE
        current_indices = block_start + tl.arange(0, BLOCK_SIZE)
        mask = current_indices < num_diag
        ptr_offsets = current_indices * diag_stride
        current_ptrs = inp_ptr + ptr_offsets
        vals = tl.load(current_ptrs, mask=mask, other=other_val)
        acc += vals.to(acc_dtype)
    final_sum = tl.sum(acc, axis=0)
    tl.store(out_ptr, final_sum.to(out_ptr.type.element_ty))

def run_flaggems_trace_kernel_8775e945(dev='cuda'):
    import torch
    inp_ptr = torch.randn((1, 1), device=dev, dtype=torch.float16)
    out_ptr = torch.randn((), device=dev, dtype=torch.float16)
    trace_kernel_8775e945[(1, 1, 1)](inp_ptr, out_ptr, 1, 1, 1, BLOCK_SIZE=1)
    return {'inp_ptr': inp_ptr, 'out_ptr': out_ptr}


