import flag_gems.utils.triton_lang_extension as ext_1235fd9f

def triu_batch_kernel_1235fd9f(X, Y, batch, MN, N, diagonal, BATCH_BLOCK_SIZE: tl.constexpr, MN_BLOCK_SIZE: tl.constexpr):
    batch_id = ext_1235fd9f.program_id(0)
    mn_id = ext_1235fd9f.program_id(1)
    row = batch_id * BATCH_BLOCK_SIZE + tl.arange(0, BATCH_BLOCK_SIZE)[:, None]
    batch_mask = row < batch
    X += row * MN
    Y += row * MN
    cols = mn_id * MN_BLOCK_SIZE + tl.arange(0, MN_BLOCK_SIZE)[None, :]
    mn_mask = cols < MN
    mask = batch_mask and mn_mask
    x = tl.load(X + cols, mask, other=0.0)
    m = cols // N
    n = cols % N
    y = tl.where(m + diagonal <= n, x, 0.0)
    tl.store(Y + cols, y, mask=mask)

