# tritonbench :: _seeded_triton_dropout
# src: https://github.com/pytorch-labs/tritonbench/blob/7cf5be34245ea8181c55a0dd21e1851ee1270ab6/tritonbench/operators/low_mem_dropout/kernels.py#L29
# validated: OK in={'x_ptr': [32], 'output_ptr': [32]} 0.227ms
# ======================================================================
@triton.jit
def _seeded_triton_dropout_715d364a(x_ptr, output_ptr, n_elements, p, seed, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(axis=0)
    block_start = pid * BLOCK_SIZE
    offsets = block_start + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    x = tl.load(x_ptr + offsets, mask=mask)
    random = tl.rand(seed, offsets)
    x_keep = random > p
    output = tl.where(x_keep, x / (1 - p), 0.0)
    tl.store(output_ptr + offsets, output, mask=mask)

