# tritonbench :: _triton_dropout
# src: https://github.com/pytorch-labs/tritonbench/blob/7cf5be34245ea8181c55a0dd21e1851ee1270ab6/tritonbench/operators/low_mem_dropout/kernels.py#L7
# validated: OK in={'x_ptr': [32], 'x_keep_ptr': [32], 'output_ptr': [32]} 0.262ms
# ======================================================================
@triton.jit
def _triton_dropout_eef0b8a0(x_ptr, x_keep_ptr, output_ptr, n_elements, p, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(axis=0)
    block_start = pid * BLOCK_SIZE
    offsets = block_start + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    x = tl.load(x_ptr + offsets, mask=mask)
    x_keep = tl.load(x_keep_ptr + offsets, mask=mask)
    output = tl.where(x_keep, x / (1 - p), 0.0)
    tl.store(output_ptr + offsets, output, mask=mask)

def run_tritonbench__triton_dropout_eef0b8a0(dev='cuda'):
    import torch
    x_ptr = torch.randn((32,), device=dev, dtype=torch.float32)
    x_keep_ptr = torch.zeros((32,), device=dev, dtype=torch.int32)
    output_ptr = torch.randn((32,), device=dev, dtype=torch.float32)
    _triton_dropout_eef0b8a0[(1, 1, 1)](x_ptr, x_keep_ptr, output_ptr, 32, 0.25, BLOCK_SIZE=1024)
    return {'x_ptr': x_ptr, 'x_keep_ptr': x_keep_ptr, 'output_ptr': output_ptr}


