# tritonbench :: softmax_kernel
# src: https://github.com/pytorch-labs/tritonbench/blob/7cf5be34245ea8181c55a0dd21e1851ee1270ab6/tritonbench/operators/softmax/operator.py#L181
# validated: OK in={'output_ptr': [4096, 256], 'input_ptr': [4096, 256]} 0.185ms
# ======================================================================
@triton.jit
def softmax_kernel_867ed7c5(output_ptr, input_ptr, input_row_stride, output_row_stride, n_cols, BLOCK_SIZE: tl.constexpr):
    row_idx = tl.program_id(0)
    row_start_ptr = input_ptr + row_idx * input_row_stride
    col_offsets = tl.arange(0, BLOCK_SIZE)
    input_ptrs = row_start_ptr + col_offsets
    row = tl.load(input_ptrs, mask=col_offsets < n_cols, other=-float('inf'))
    row_minus_max = row - tl.max(row, axis=0)
    numerator = tl.exp(row_minus_max)
    denominator = tl.sum(numerator, axis=0)
    softmax_output = numerator / denominator
    output_row_start_ptr = output_ptr + row_idx * output_row_stride
    output_ptrs = output_row_start_ptr + col_offsets
    tl.store(output_ptrs, softmax_output, mask=col_offsets < n_cols)

def run_tritonbench_softmax_kernel_867ed7c5(dev='cuda'):
    import torch
    output_ptr = torch.randn((4096, 256), device=dev, dtype=torch.float16)
    input_ptr = torch.randn((4096, 256), device=dev, dtype=torch.float16)
    softmax_kernel_867ed7c5[(4096, 1, 1)](output_ptr, input_ptr, 256, 256, 256, BLOCK_SIZE=256)
    return {'output_ptr': output_ptr, 'input_ptr': input_ptr}


